import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';
import {Oruzje, OruzjeService} from "../../services/oruzje.service";

declare var bootstrap: any;

@Component({
  selector: 'app-oruzje',
  templateUrl: './oruzje.component.html',
  styleUrls: ['./oruzje.component.css']
})
export class OruzjeComponent implements OnInit, AfterViewInit {

  @ViewChild('oruzjeModal', { static: false }) oruzjeModalRef!: ElementRef;
  kategorijeOpcije: string[] = ['A', 'B', 'C', 'D', 'E'];

  oruzja: Oruzje[] = [];
  token: string = '';
  rola: string = '';

  noviZahtev: any = { ime: '', prezime: '', kategorijaOruzja: [] };
  modalInstance: any;

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'success';

  constructor(private oruzjeService: OruzjeService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajOruzja();
  }

  ngAfterViewInit(): void {
    if (this.oruzjeModalRef && this.oruzjeModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.oruzjeModalRef.nativeElement);
    }
  }

  openOruzjeModal(): void {
    if (this.modalInstance) this.modalInstance.show();
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    // Payload šaljemo samo sa datumom i kategorijama
    const payload = {
      datumOd: new Date(),  // današnji datum
      kategorijaOruzja: this.noviZahtev.kategorijaOruzja
    };

    this.oruzjeService.podnesiZahtev(payload).subscribe({
      next: res => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm();
        this.noviZahtev = { kategorijaOruzja: [] }; // reset kategorija
        this.ucitajOruzja();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Zahtev uspešno podnet!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Došlo je do greške pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });
  }


  ucitajOruzja(): void {
    this.oruzjeService.dohvatiSve().subscribe({
      next: res => this.oruzja = res,
      error: err => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    return this.oruzja.some(z => z.status === 'CEKANJE' || z.status === 'DOZVOLJEN');
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

  prihvatiZahtev(id: number) {
    this.oruzjeService.odobriZahtev(id).subscribe({
      next: res => {
        this.ucitajOruzja();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Zahtev odobren!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Greška pri odobravanju zahteva.';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.oruzjeService.odbijZahtev(id).subscribe({
      next: res => {
        this.ucitajOruzja();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Zahtev odbijen!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Greška pri odbijanju zahteva.';
        this.showAlert = true;
      }
    });
  }
}
<div class="container mt-5">

  <!-- Alert komponenta -->
  <app-custom-alert
    *ngIf="showAlert"
    [message]="alertMessage"
    [type]="alertType"
    (closed)="closeAlert()">
  </app-custom-alert>

  <!-- Dugme za podnošenje zahteva za oružje -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!imaAktivanZahtev && !isEmployer">
    <button class="btn btn-primary" (click)="openOruzjeModal()">Podnesi zahtev za oružje</button>
  </div>

  <!-- Tabela zahteva za oružje -->
  <h3 class="mb-3 text-center">
    {{ isEmployer ? 'Zahtevi za oružje' : 'Moji zahtevi za oružje' }}
  </h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Datum od</th>
        <th>Datum do</th>
        <th>Reg. broj</th>
        <th>Kategorija</th>
        <th *ngIf="isEmployer">Status</th>
        <th *ngIf="isEmployer">Akcija</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let oruzje of oruzja; let i = index">
        <tr *ngIf="isEmployer || oruzje.status === 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ oruzje.ime }}</td>
          <td>{{ oruzje.prezime }}</td>
          <td>{{ oruzje.datumOd | date:'dd.MM.yyyy' }}</td>
          <td>{{ oruzje.datumDo | date:'dd.MM.yyyy' }}</td>
          <td>{{ oruzje.regBroj }}</td>
          <td>{{ oruzje.kategorijaOruzja }}</td>
          <td *ngIf="isEmployer">{{ oruzje.status }}</td>
          <td *ngIf="isEmployer">
            <ng-container *ngIf="oruzje.status !== 'DOZVOLJEN' && oruzje.status !== 'ODBIJEN'">
              <button class="btn btn-success btn-sm me-2" (click)="prihvatiZahtev(oruzje.id)">Prihvati</button>
              <button class="btn btn-danger btn-sm" (click)="odbijZahtev(oruzje.id)">Odbij</button>
            </ng-container>
          </td>
        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>

  <!-- Modal za podnošenje zahteva -->
  <div class="modal fade" id="oruzjeModal" #oruzjeModal tabindex="-1" aria-labelledby="oruzjeModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="oruzjeModalLabel">Podnesi zahtev za oružje</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
        </div>
        <div class="modal-body">
          <form #oruzjeForm="ngForm" (ngSubmit)="podnesiZahtev(oruzjeForm)">
            <div class="mb-3">
              <label for="ime" class="form-label">Ime</label>
              <input type="text" class="form-control" id="ime" name="ime"
                     [(ngModel)]="noviZahtev.ime"
                     required #imeModel="ngModel">
              <div class="text-danger" *ngIf="imeModel.invalid && imeModel.touched">
                Ime je obavezno.
              </div>
            </div>

            <div class="mb-3">
              <label for="prezime" class="form-label">Prezime</label>
              <input type="text" class="form-control" id="prezime" name="prezime"
                     [(ngModel)]="noviZahtev.prezime"
                     required #prezimeModel="ngModel">
              <div class="text-danger" *ngIf="prezimeModel.invalid && prezimeModel.touched">
                Prezime je obavezno.
              </div>
            </div>

            <div class="mb-3">
              <label for="kategorijaOruzja" class="form-label">Kategorije oružja</label>
              <select class="form-select" id="kategorijaOruzja" name="kategorijaOruzja"
                      [(ngModel)]="noviZahtev.kategorijaOruzja"
                      multiple
                      required #katModel="ngModel">
                <option *ngFor="let kat of kategorijeOpcije" [value]="kat">{{ kat }}</option>
              </select>
              <div class="text-danger" *ngIf="katModel.invalid && katModel.touched">
                Morate izabrati bar jednu kategoriju.
              </div>
            </div>

            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary" [disabled]="oruzjeForm.invalid">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
